-- 「오늘의 록」 곡 데이터 — PostgreSQL / Supabase용
--
-- 실행 방법 (둘 중 하나)
--   Supabase: 대시보드 → SQL Editor → New query → 이 파일 내용 전체 붙여넣기 → Run
--   psql:     psql "$DATABASE_URL" -f db/todays_rock.sql
--
-- 주의: 곡 관련 뷰·테이블(songs, song_moods, song_weathers, v_songs)을 지우고 다시 만듭니다.
--       회원 테이블(account_로 시작)은 곡 테이블을 참조하지 않으므로 그대로 유지됩니다.

BEGIN;

-- 다시 실행해도 되도록 기존 뷰·테이블 정리
DROP VIEW  IF EXISTS v_songs;
DROP TABLE IF EXISTS song_weathers;
DROP TABLE IF EXISTS song_moods;
DROP TABLE IF EXISTS songs;

-- 1) 곡 정보
CREATE TABLE songs (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title      VARCHAR(200) NOT NULL,
  artist     VARCHAR(200) NOT NULL,
  year       SMALLINT     NOT NULL,
  genre      VARCHAR(100) NOT NULL,
  energy     SMALLINT     NOT NULL CHECK (energy BETWEEN 1 AND 5),
  theme      VARCHAR(255),
  tone       VARCHAR(255),
  reason     VARCHAR(500),
  lyrics_url VARCHAR(500),
  CONSTRAINT uq_title_artist UNIQUE (title, artist)
);

-- 2) 곡별 기분 (한 곡에 여러 개)
CREATE TABLE song_moods (
  song_id INTEGER NOT NULL REFERENCES songs(id) ON DELETE CASCADE,
  mood    TEXT    NOT NULL CHECK (mood IN ('calm','excited','focused','blue','tired','frustrated')),
  PRIMARY KEY (song_id, mood)
);

-- 3) 곡별 날씨 (한 곡에 여러 개)
CREATE TABLE song_weathers (
  song_id INTEGER NOT NULL REFERENCES songs(id) ON DELETE CASCADE,
  weather TEXT    NOT NULL CHECK (weather IN ('clear','cloudy','rain','snow')),
  PRIMARY KEY (song_id, weather)
);

-- 곡 데이터 (500곡 + 아래 433곡 = 933곡)
INSERT INTO songs (id, title, artist, year, genre, energy, theme, tone, reason, lyrics_url) VALUES
(1, 'Don''t Look Back in Anger', 'Oasis', 1995, 'Britpop', 3, '후회와 분노를 지나 과거를 놓아주는 태도', '쓸쓸하게 시작해 거대한 합창으로 벅차오르는 분위기', '천천히 고조되는 합창이 복잡한 마음을 바깥으로 밀어냅니다.', 'https://genius.com/Oasis-dont-look-back-in-anger-lyrics'),
(2, 'Dreams', 'The Cranberries', 1992, 'Alternative Rock', 3, '사랑에 빠지며 달라지는 마음과 새로운 가능성', '투명하고 들뜬 공기감이 번지는 몽환적인 분위기', '가볍게 떠오르는 기타와 목소리가 하루의 공기를 환기합니다.', 'https://genius.com/The-cranberries-dreams-lyrics'),
(3, 'Heroes', 'David Bowie', 1977, 'Art Rock', 4, '완전하지 않아도 단 하루만큼은 용기 내는 두 사람', '절제된 시작에서 장엄하게 상승하는 분위기', '지친 날에도 단 한 번은 앞으로 나아가게 만드는 거대한 곡입니다.', 'https://genius.com/David-bowie-heroes-lyrics'),
(4, 'Here Comes the Sun', 'The Beatles', 1969, 'Folk Rock', 2, '긴 어려움이 지나고 다시 찾아오는 희망', '따뜻한 햇살처럼 부드럽고 낙관적인 분위기', '맑은 빛처럼 들어오는 기타가 굳은 마음을 느슨하게 풉니다.', 'https://genius.com/The-beatles-here-comes-the-sun-lyrics'),
(5, 'Everlong', 'Foo Fighters', 1997, 'Alternative Rock', 5, '시간이 멈추길 바랄 만큼 강렬한 관계의 순간', '숨 가쁘게 달리면서도 아련함이 남는 분위기', '폭발적인 기타와 달리는 리듬이 쌓인 에너지를 꺼내줍니다.', 'https://genius.com/Foo-fighters-everlong-lyrics'),
(6, 'Linger', 'The Cranberries', 1993, 'Dream Pop', 2, '끝난 관계에서 미처 놓지 못한 미련과 상처', '섬세하고 서정적이며 비 오는 날처럼 촉촉한 분위기', '비 오는 날의 잔상처럼 오래 남는 감정을 조용히 받아줍니다.', 'https://genius.com/The-cranberries-linger-lyrics'),
(7, 'Mr. Brightside', 'The Killers', 2003, 'Indie Rock', 5, '질투와 불안이 머릿속에서 걷잡을 수 없이 커지는 순간', '초조하지만 춤추게 만드는 폭발적인 분위기', '멈추지 않는 비트가 답답한 기분을 단숨에 움직이게 합니다.', 'https://genius.com/The-killers-mr-brightside-lyrics'),
(8, 'Wish You Were Here', 'Pink Floyd', 1975, 'Progressive Rock', 1, '부재한 사람을 향한 그리움과 진짜 삶에 대한 질문', '담담하고 고독하며 넓은 여백이 느껴지는 분위기', '여백이 많은 기타 선율이 생각을 서두르지 않게 해줍니다.', 'https://genius.com/Pink-floyd-wish-you-were-here-lyrics'),
(9, 'Song 2', 'Blur', 1997, 'Alternative Rock', 5, '의미보다 순간의 충동과 에너지를 터뜨리는 쾌감', '짧고 거칠며 장난스럽게 폭발하는 분위기', '짧고 강한 폭발력으로 처진 에너지를 빠르게 끌어올립니다.', 'https://genius.com/Blur-song-2-lyrics'),
