(11, 'Where Is My Mind?', 'Pixies', 1988, 'Alternative Rock', 2, '현실감이 흐려지는 혼란과 자기 인식의 순간', '기묘하고 공중에 떠 있는 듯한 초현실적 분위기', '낯설고 반복적인 리듬이 복잡한 생각에 새로운 간격을 만듭니다.', 'https://genius.com/Pixies-where-is-my-mind-lyrics'),
