(86, 'Hey Hey Hey', '자우림', 1997, 'Korean Alternative Rock', 4, '억눌림을 털고 자기 방식대로 살아가는 태도', '발랄하고 반항적이며 자유로운 분위기', '선명한 리듬과 고조되는 사운드가 굳은 기분을 움직입니다.', 'https://search.naver.com/search.naver?query=%EC%9E%90%EC%9A%B0%EB%A6%BC%20Hey%20Hey%20Hey%20%EA%B0%80%EC%82%AC'),
