(88, '나는 나비', 'YB', 2006, 'Korean Rock', 5, '고통스러운 성장을 지나 자유롭게 날아가는 꿈', '희망차고 힘차며 함께 부르는 분위기', '강한 추진력과 폭발적인 사운드가 정체된 에너지를 깨웁니다.', 'https://search.naver.com/search.naver?query=YB%20%EB%82%98%EB%8A%94%20%EB%82%98%EB%B9%84%20%EA%B0%80%EC%82%AC'),
(89, '기억을 걷는 시간', '넬', 2008, 'Korean Modern Rock', 2, '일상 곳곳에 남은 헤어진 사람의 기억', '차갑고 섬세하며 잔향이 긴 분위기', '잔잔한 흐름이 오늘의 감정을 무리 없이 받아들이게 합니다.', 'https://search.naver.com/search.naver?query=%EB%84%AC%20%EA%B8%B0%EC%96%B5%EC%9D%84%20%EA%B1%B7%EB%8A%94%20%EC%8B%9C%EA%B0%84%20%EA%B0%80%EC%82%AC'),
