(92, 'TOMBOY', '혁오', 2017, 'Korean Indie Rock', 2, '성장과 사랑 앞에서 미숙한 자신을 인정하는 마음', '나른하고 쓸쓸하며 청춘다운 분위기', '잔잔한 흐름이 오늘의 감정을 무리 없이 받아들이게 합니다.', 'https://search.naver.com/search.naver?query=%ED%98%81%EC%98%A4%20TOMBOY%20%EA%B0%80%EC%82%AC'),
(93, '주저하는 연인들을 위해', '잔나비', 2019, 'Korean Indie Rock', 3, '끝을 두려워해 사랑을 망설이는 이들을 향한 위로', '낭만적이고 복고적이며 벅찬 분위기', '균형 잡힌 리듬이 마음의 온도를 자연스럽게 바꿔줍니다.', 'https://search.naver.com/search.naver?query=%EC%9E%94%EB%82%98%EB%B9%84%20%EC%A3%BC%EC%A0%80%ED%95%98%EB%8A%94%20%EC%97%B0%EC%9D%B8%EB%93%A4%EC%9D%84%20%EC%9C%84%ED%95%B4%20%EA%B0%80%EC%82%AC'),
(94, '긴 꿈', '새소년', 2017, 'Korean Indie Rock', 3, '현실과 꿈 사이에서 오래 떠도는 청춘', '몽환적이고 거칠며 깊은 밤 같은 분위기', '균형 잡힌 리듬이 마음의 온도를 자연스럽게 바꿔줍니다.', 'https://search.naver.com/search.naver?query=%EC%83%88%EC%86%8C%EB%85%84%20%EA%B8%B4%20%EA%BF%88%20%EA%B0%80%EC%82%AC'),
(95, 'NO PAIN', '실리카겔', 2022, 'Korean Alternative Rock', 5, '고통을 뚫고 감각과 생명력을 되찾는 움직임', '미래적이고 폭발적이며 황홀한 분위기', '강한 추진력과 폭발적인 사운드가 정체된 에너지를 깨웁니다.', 'https://search.naver.com/search.naver?query=%EC%8B%A4%EB%A6%AC%EC%B9%B4%EA%B2%94%20NO%20PAIN%20%EA%B0%80%EC%82%AC'),
(96, 'Highlight', '터치드', 2023, 'Korean Rock', 5, '무대와 삶의 가장 빛나는 순간을 붙잡는 열망', '화려하고 힘차며 공연장 같은 분위기', '강한 추진력과 폭발적인 사운드가 정체된 에너지를 깨웁니다.', 'https://search.naver.com/search.naver?query=%ED%84%B0%EC%B9%98%EB%93%9C%20Highlight%20%EA%B0%80%EC%82%AC'),
(97, '입춘', '한로로', 2022, 'Korean Indie Rock', 3, '혹독한 계절 끝에 오는 작은 시작과 위로', '차갑지만 끝내 따뜻해지는 분위기', '균형 잡힌 리듬이 마음의 온도를 자연스럽게 바꿔줍니다.', 'https://search.naver.com/search.naver?query=%ED%95%9C%EB%A1%9C%EB%A1%9C%20%EC%9E%85%EC%B6%98%20%EA%B0%80%EC%82%AC'),
(98, 'EVERYTHING', '검정치마', 2015, 'Korean Indie Rock', 2, '한 사람이 자신의 전부가 되어버린 사랑', '나른하고 다정하며 사적인 분위기', '잔잔한 흐름이 오늘의 감정을 무리 없이 받아들이게 합니다.', 'https://search.naver.com/search.naver?query=%EA%B2%80%EC%A0%95%EC%B9%98%EB%A7%88%20EVERYTHING%20%EA%B0%80%EC%82%AC'),
(99, '들려주고 싶었던', '이승윤', 2021, 'Korean Rock', 4, '끝내 전하지 못한 말과 음악을 건네는 마음', '진솔하고 역동적이며 벅찬 분위기', '선명한 리듬과 고조되는 사운드가 굳은 기분을 움직입니다.', 'https://search.naver.com/search.naver?query=%EC%9D%B4%EC%8A%B9%EC%9C%A4%20%EB%93%A4%EB%A0%A4%EC%A3%BC%EA%B3%A0%20%EC%8B%B6%EC%97%88%EB%8D%98%20%EA%B0%80%EC%82%AC'),
