INSERT INTO songs (id, title, artist, year, genre, energy, theme, tone, reason, lyrics_url) VALUES
(101, 'God Only Knows', 'The Beach Boys', 1966, 'Baroque Pop', 2, '사랑하는 사람이 없는 삶을 상상할 수 없는 깊은 애정', '차분한 전개 속에서 감정이 천천히 스며드는 내밀한 분위기', '느린 호흡과 섬세한 정서가 지친 마음을 조용히 가라앉힙니다.', 'https://genius.com/the-beach-boys-god-only-knows-lyrics'),
(102, 'A Day in the Life', 'The Beatles', 1967, 'Psychedelic Rock', 3, '일상의 파편 속에서 드러나는 현대인의 불안', '서정적인 흐름과 Psychedelic Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://genius.com/the-beatles-a-day-in-the-life-lyrics'),
(103, 'While My Guitar Gently Weeps', 'The Beatles', 1968, 'Blues Rock', 3, '세상의 무심함을 바라보는 슬픔과 연민', '서정적인 흐름과 Blues Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://genius.com/the-beatles-while-my-guitar-gently-weeps-lyrics'),
(104, 'Let It Be', 'The Beatles', 1970, 'Rock', 2, '혼란 속에서도 흐름을 받아들이는 위로', '차분한 전개 속에서 감정이 천천히 스며드는 내밀한 분위기', '느린 호흡과 섬세한 정서가 지친 마음을 조용히 가라앉힙니다.', 'https://genius.com/the-beatles-let-it-be-lyrics'),
(105, 'Sympathy for the Devil', 'The Rolling Stones', 1968, 'Rock', 4, '역사 속 폭력과 인간 내면의 악을 바라보는 시선', 'Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://genius.com/the-rolling-stones-sympathy-for-the-devil-lyrics'),
(106, '(I Can''t Get No) Satisfaction', 'The Rolling Stones', 1965, 'Rock', 5, '소비사회와 채워지지 않는 욕망에 대한 불만', 'Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/the-rolling-stones-i-cant-get-no-satisfaction-lyrics'),
(107, 'Light My Fire', 'The Doors', 1967, 'Psychedelic Rock', 4, '위험할 만큼 뜨거운 욕망과 해방감', 'Psychedelic Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://genius.com/the-doors-light-my-fire-lyrics'),
(108, 'Riders on the Storm', 'The Doors', 1971, 'Psychedelic Rock', 2, '폭풍 속을 떠도는 여행자의 불안과 고독', '차분한 전개 속에서 감정이 천천히 스며드는 내밀한 분위기', '느린 호흡과 섬세한 정서가 지친 마음을 조용히 가라앉힙니다.', 'https://genius.com/the-doors-riders-on-the-storm-lyrics'),
(109, 'Somebody to Love', 'Jefferson Airplane', 1967, 'Psychedelic Rock', 5, '사랑과 연결을 갈구하는 절박함', 'Psychedelic Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/jefferson-airplane-somebody-to-love-lyrics'),
(110, 'You Really Got Me', 'The Kinks', 1964, 'Garage Rock', 5, '상대를 향한 통제할 수 없는 매혹', 'Garage Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/the-kinks-you-really-got-me-lyrics'),
(111, 'The House of the Rising Sun', 'The Animals', 1964, 'Folk Rock', 3, '파멸의 길을 되돌아보는 처연한 고백', '서정적인 흐름과 Folk Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://genius.com/the-animals-the-house-of-the-rising-sun-lyrics'),
(112, 'Sunshine of Your Love', 'Cream', 1967, 'Blues Rock', 4, '밤을 지나 연인을 기다리는 강렬한 열망', 'Blues Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://genius.com/cream-sunshine-of-your-love-lyrics'),
(113, 'Piece of My Heart', 'Big Brother & the Holding Company', 1968, 'Blues Rock', 5, '상처받으면서도 사랑을 내어주는 격정', 'Blues Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/big-brother-and-the-holding-company-piece-of-my-heart-lyrics'),
(114, 'Purple Haze', 'Jimi Hendrix', 1967, 'Psychedelic Rock', 5, '현실 감각을 뒤흔드는 혼란과 황홀', 'Psychedelic Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/jimi-hendrix-purple-haze-lyrics'),
(115, 'Bad Moon Rising', 'Creedence Clearwater Revival', 1969, 'Roots Rock', 4, '다가오는 위기를 밝은 리듬으로 경고하는 역설', 'Roots Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://genius.com/creedence-clearwater-revival-bad-moon-rising-lyrics'),
(116, 'My Generation', 'The Who', 1965, 'Rock', 5, '기성세대에 맞서는 청춘의 선언', 'Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/the-who-my-generation-lyrics'),
(117, 'The Sound of Silence', 'Simon & Garfunkel', 1964, 'Folk Rock', 2, '소통이 끊긴 사회와 깊은 고독', '차분한 전개 속에서 감정이 천천히 스며드는 내밀한 분위기', '느린 호흡과 섬세한 정서가 지친 마음을 조용히 가라앉힙니다.', 'https://genius.com/simon-and-garfunkel-the-sound-of-silence-lyrics'),
(118, 'Bohemian Rhapsody', 'Queen', 1975, 'Art Rock', 5, '죄책감과 운명에 맞서는 극적인 내면극', 'Art Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/queen-bohemian-rhapsody-lyrics'),
(119, 'Somebody to Love', 'Queen', 1976, 'Rock', 5, '진실한 사랑을 찾고 싶은 간절함', 'Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://genius.com/queen-somebody-to-love-lyrics'),
