(281, 'Good Night', '넬', 2003, 'Korean Alternative Rock', 2, '떠나는 사람에게 조용히 건네는 마지막 인사', '차분한 전개 속에서 감정이 천천히 스며드는 내밀한 분위기', '느린 호흡과 섬세한 정서가 지친 마음을 조용히 가라앉힙니다.', 'https://search.naver.com/search.naver?query=%EB%84%AC%20Good%20Night%20%EA%B0%80%EC%82%AC'),
