(286, '밤이 깊었네', '크라잉넛', 2001, 'Korean Punk Rock', 4, '늦은 밤 떠나간 사람을 기다리는 쓸쓸함', 'Korean Punk Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://search.naver.com/search.naver?query=%ED%81%AC%EB%9D%BC%EC%9E%89%EB%84%9B%20%EB%B0%A4%EC%9D%B4%20%EA%B9%8A%EC%97%88%EB%84%A4%20%EA%B0%80%EC%82%AC'),
(287, '챠우챠우', '델리스파이스', 1997, 'Korean Indie Rock', 3, '머릿속에서 떠나지 않는 사랑의 목소리', '서정적인 흐름과 Korean Indie Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://search.naver.com/search.naver?query=%EB%8D%B8%EB%A6%AC%EC%8A%A4%ED%8C%8C%EC%9D%B4%EC%8A%A4%20%EC%B1%A0%EC%9A%B0%EC%B1%A0%EC%9A%B0%20%EA%B0%80%EC%82%AC'),
(288, '고백', '델리스파이스', 2003, 'Korean Indie Rock', 3, '오래 품어온 마음을 조심스럽게 전하는 순간', '서정적인 흐름과 Korean Indie Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://search.naver.com/search.naver?query=%EB%8D%B8%EB%A6%AC%EC%8A%A4%ED%8C%8C%EC%9D%B4%EC%8A%A4%20%EA%B3%A0%EB%B0%B1%20%EA%B0%80%EC%82%AC'),
(289, '아름다운 것', '언니네 이발관', 2008, 'Korean Indie Rock', 3, '사라지는 아름다움과 관계를 붙드는 슬픔', '서정적인 흐름과 Korean Indie Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://search.naver.com/search.naver?query=%EC%96%B8%EB%8B%88%EB%84%A4%20%EC%9D%B4%EB%B0%9C%EA%B4%80%20%EC%95%84%EB%A6%84%EB%8B%A4%EC%9A%B4%20%EA%B2%83%20%EA%B0%80%EC%82%AC'),
(290, '기다린 만큼, 더', '검정치마', 2016, 'Korean Indie Rock', 3, '오래 기다린 사랑만큼 커진 기대와 상처', '서정적인 흐름과 Korean Indie Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://search.naver.com/search.naver?query=%EA%B2%80%EC%A0%95%EC%B9%98%EB%A7%88%20%EA%B8%B0%EB%8B%A4%EB%A6%B0%20%EB%A7%8C%ED%81%BC%2C%20%EB%8D%94%20%EA%B0%80%EC%82%AC'),
(291, '와리가리', '혁오', 2015, 'Korean Indie Rock', 4, '어디에도 정착하지 못하고 오가는 청춘의 마음', 'Korean Indie Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://search.naver.com/search.naver?query=%ED%98%81%EC%98%A4%20%EC%99%80%EB%A6%AC%EA%B0%80%EB%A6%AC%20%EA%B0%80%EC%82%AC'),
(292, 'Comes And Goes', '혁오', 2015, 'Korean Indie Rock', 4, '감정과 관계가 오고 가는 흐름을 받아들이는 태도', 'Korean Indie Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://search.naver.com/search.naver?query=%ED%98%81%EC%98%A4%20Comes%20And%20Goes%20%EA%B0%80%EC%82%AC'),
(293, '뜨거운 여름밤은 가고 남은 건 볼품없지만', '잔나비', 2016, 'Korean Indie Rock', 3, '찬란했던 계절 뒤에 남은 사랑과 허무', '서정적인 흐름과 Korean Indie Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://search.naver.com/search.naver?query=%EC%9E%94%EB%82%98%EB%B9%84%20%EB%9C%A8%EA%B1%B0%EC%9A%B4%20%EC%97%AC%EB%A6%84%EB%B0%A4%EC%9D%80%20%EA%B0%80%EA%B3%A0%20%EB%82%A8%EC%9D%80%20%EA%B1%B4%20%EB%B3%BC%ED%92%88%EC%97%86%EC%A7%80%EB%A7%8C%20%EA%B0%80%EC%82%AC'),
(294, '파도', '새소년', 2017, 'Korean Indie Rock', 4, '밀려오는 감정과 변화에 몸을 맡기는 노래', 'Korean Indie Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://search.naver.com/search.naver?query=%EC%83%88%EC%86%8C%EB%85%84%20%ED%8C%8C%EB%8F%84%20%EA%B0%80%EC%82%AC'),
(295, 'Vitriol', '국카스텐', 2008, 'Korean Alternative Rock', 5, '날카로운 감정과 자기파괴적 에너지를 분출하는 노래', 'Korean Alternative Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://search.naver.com/search.naver?query=%EA%B5%AD%EC%B9%B4%EC%8A%A4%ED%85%90%20Vitriol%20%EA%B0%80%EC%82%AC'),
(296, 'Tik Tak Tok', '실리카겔', 2023, 'Korean Indie Rock', 5, '시간의 압박과 불안을 기묘한 리듬으로 밀어붙이는 노래', 'Korean Indie Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://search.naver.com/search.naver?query=%EC%8B%A4%EB%A6%AC%EC%B9%B4%EA%B2%94%20Tik%20Tak%20Tok%20%EA%B0%80%EC%82%AC'),
(297, '야경', '터치드', 2022, 'Korean Rock', 5, '도시의 밤을 배경으로 다시 살아나는 감정', 'Korean Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://search.naver.com/search.naver?query=%ED%84%B0%EC%B9%98%EB%93%9C%20%EC%95%BC%EA%B2%BD%20%EA%B0%80%EC%82%AC'),
(298, '사랑하게 될 거야', '한로로', 2023, 'Korean Indie Rock', 4, '상처 이후에도 다시 사랑하게 되리라는 믿음', 'Korean Indie Rock의 선명한 리듬과 긴장감이 균형을 이루는 분위기', '또렷한 리듬이 복잡한 생각을 정리하고 기분을 전환해줍니다.', 'https://search.naver.com/search.naver?query=%ED%95%9C%EB%A1%9C%EB%A1%9C%20%EC%82%AC%EB%9E%91%ED%95%98%EA%B2%8C%20%EB%90%A0%20%EA%B1%B0%EC%95%BC%20%EA%B0%80%EC%82%AC'),
(299, '눈', 'SURL', 2018, 'Korean Indie Rock', 3, '눈 내리는 풍경에 겹쳐지는 그리움', '서정적인 흐름과 Korean Indie Rock의 깊은 여운이 번지는 분위기', '선명한 멜로디와 여운이 현재의 감정을 자연스럽게 따라갑니다.', 'https://search.naver.com/search.naver?query=SURL%20%EB%88%88%20%EA%B0%80%EC%82%AC'),
(300, '개화', 'LUCY', 2020, 'Korean Pop Rock', 5, '긴 기다림 끝에 꽃처럼 피어나는 시작', 'Korean Pop Rock 특유의 강한 추진력과 폭발적인 후렴이 살아 있는 분위기', '강한 리듬과 후렴이 가라앉은 에너지를 단숨에 끌어올립니다.', 'https://search.naver.com/search.naver?query=LUCY%20%EA%B0%9C%ED%99%94%20%EA%B0%80%EC%82%AC');

INSERT INTO songs (id, title, artist, year, genre, energy, theme, tone, reason, lyrics_url) VALUES
(301, 'Across the Universe', 'The Beatles', 1969, 'Psychedelic Rock', 1, '흘러가는 생각과 마음', '몽환적인 어쿠스틱과 부드러운 보컬', '‘Across the Universe’에서는 흘러가는 생각과 마음이라는 정서가 몽환적인 어쿠스틱과 부드러운 보컬 속에 스며들어요.', 'https://genius.com/search?q=The%20Beatles%20Across%20the%20Universe'),
(302, 'Pale Blue Eyes', 'The Velvet Underground', 1969, 'Art Rock', 1, '사랑의 기억과 거리감', '나지막한 목소리와 느린 기타', '‘Pale Blue Eyes’의 핵심은 사랑의 기억과 거리감. 나지막한 목소리와 느린 기타에 귀 기울여 보세요.', 'https://genius.com/search?q=The%20Velvet%20Underground%20Pale%20Blue%20Eyes'),
(303, 'River Man', 'Nick Drake', 1969, 'Folk Rock', 1, '시간과 고독', '현악과 어쿠스틱 기타의 깊은 울림', 'Nick Drake가 그려 내는 시간과 고독. 현악과 어쿠스틱 기타의 깊은 울림 덕분에 오래 여운이 남아요.', 'https://genius.com/search?q=Nick%20Drake%20River%20Man'),
(304, 'Time of the Season', 'The Zombies', 1968, 'Psychedelic Rock', 2, '계절과 호기심', '절제된 리듬과 몽환적인 화음', '계절과 호기심을 생각하게 하는 곡. 특히 절제된 리듬과 몽환적인 화음이 인상적이에요.', 'https://genius.com/search?q=The%20Zombies%20Time%20of%20the%20Season'),
(305, 'Turn! Turn! Turn!', 'The Byrds', 1965, 'Folk Rock', 2, '변화와 순환', '맑은 기타와 차분한 합창', '‘Turn! Turn! Turn!’에서는 변화와 순환이라는 정서가 맑은 기타와 차분한 합창 속에 스며들어요.', 'https://genius.com/search?q=The%20Byrds%20Turn%21%20Turn%21%20Turn%21'),
(306, 'In My Room', 'The Beach Boys', 1963, 'Baroque Pop', 1, '혼자만의 안식처', '포근한 화음과 단정한 멜로디', '‘In My Room’의 핵심은 혼자만의 안식처. 포근한 화음과 단정한 멜로디에 귀 기울여 보세요.', 'https://genius.com/search?q=The%20Beach%20Boys%20In%20My%20Room'),
(307, 'Waterloo Sunset', 'The Kinks', 1967, 'Soft Rock', 1, '도시의 저녁과 관조', '잔잔한 기타와 따뜻한 보컬', 'The Kinks가 그려 내는 도시의 저녁과 관조. 잔잔한 기타와 따뜻한 보컬 덕분에 오래 여운이 남아요.', 'https://genius.com/search?q=The%20Kinks%20Waterloo%20Sunset'),
(308, 'A Whiter Shade of Pale', 'Procol Harum', 1967, 'Art Rock', 1, '흐릿한 기억과 상실', '오르간이 이끄는 서정적인 흐름', '흐릿한 기억과 상실을 생각하게 하는 곡. 특히 오르간이 이끄는 서정적인 흐름이 인상적이에요.', 'https://genius.com/search?q=Procol%20Harum%20A%20Whiter%20Shade%20of%20Pale'),
(309, 'It''s Too Late', 'Carole King', 1971, 'Soft Rock', 2, '끝난 관계를 받아들이기', '담담한 피아노와 절제된 리듬', '‘It''s Too Late’에서는 끝난 관계를 받아들이기이라는 정서가 담담한 피아노와 절제된 리듬 속에 스며들어요.', 'https://genius.com/search?q=Carole%20King%20It%27s%20Too%20Late'),
(310, 'Heart of Gold', 'Neil Young', 1972, 'Folk Rock', 2, '진심을 찾아가는 길', '소박한 기타와 하모니카', '‘Heart of Gold’의 핵심은 진심을 찾아가는 길. 소박한 기타와 하모니카에 귀 기울여 보세요.', 'https://genius.com/search?q=Neil%20Young%20Heart%20of%20Gold'),
(311, 'A Horse with No Name', 'America', 1971, 'Folk Rock', 2, '낯선 풍경과 이동', '건조한 어쿠스틱 반복 리듬', 'America가 그려 내는 낯선 풍경과 이동. 건조한 어쿠스틱 반복 리듬 덕분에 오래 여운이 남아요.', 'https://genius.com/search?q=America%20A%20Horse%20with%20No%20Name'),
(312, 'These Days', 'Jackson Browne', 1973, 'Folk Rock', 1, '지난 선택과 회고', '느린 기타와 담백한 목소리', '지난 선택과 회고을 생각하게 하는 곡. 특히 느린 기타와 담백한 목소리이 인상적이에요.', 'https://genius.com/search?q=Jackson%20Browne%20These%20Days'),
(313, 'Echoes', 'Pink Floyd', 1971, 'Progressive Rock', 2, '거리와 연결', '길게 펼쳐지는 실험적 사운드', '‘Echoes’에서는 거리와 연결이라는 정서가 길게 펼쳐지는 실험적 사운드 속에 스며들어요.', 'https://genius.com/search?q=Pink%20Floyd%20Echoes'),
