(398, '수고했어, 오늘도', '옥상달빛', 2011, 'Korean Indie Pop', 1, '하루를 버틴 사람에게', '담백한 화음과 다정한 멜로디', '‘수고했어, 오늘도’의 핵심은 하루를 버틴 사람에게. 담백한 화음과 다정한 멜로디에 귀 기울여 보세요.', 'https://genius.com/search?q=%EC%98%A5%EC%83%81%EB%8B%AC%EB%B9%9B%20%EC%88%98%EA%B3%A0%ED%96%88%EC%96%B4%2C%20%EC%98%A4%EB%8A%98%EB%8F%84'),
(399, 'Antifreeze', '검정치마', 2010, 'Korean Indie Rock', 1, '차가운 계절의 사랑', '나른한 보컬과 서정적인 기타', '검정치마가 그려 내는 차가운 계절의 사랑. 나른한 보컬과 서정적인 기타 덕분에 오래 여운이 남아요.', 'https://genius.com/search?q=%EA%B2%80%EC%A0%95%EC%B9%98%EB%A7%88%20Antifreeze'),
(400, '난춘', '새소년', 2020, 'Korean Indie Rock', 2, '상처 이후의 계절', '애틋한 기타와 힘 있는 보컬', '상처 이후의 계절을 생각하게 하는 곡. 특히 애틋한 기타와 힘 있는 보컬이 인상적이에요.', 'https://genius.com/search?q=%EC%83%88%EC%86%8C%EB%85%84%20%EB%82%9C%EC%B6%98');

INSERT INTO songs (id, title, artist, year, genre, energy, theme, tone, reason, lyrics_url) VALUES
(401, 'Pink Moon', 'Nick Drake', 1972, 'Folk Rock', 2, '달빛 아래 드러나는 불안', '짧고 메마른 기타와 속삭이는 목소리', '군더더기 없는 연주가 밤의 적막을 더 선명하게 만들어 줘요.', 'https://genius.com/search?q=Nick%20Drake%20Pink%20Moon'),
(402, 'Place to Be', 'Nick Drake', 1972, 'Folk Rock', 2, '지나온 자리와 달라진 자신', '여백이 많은 어쿠스틱 포크', '오래된 사진을 넘기듯 느릿한 기타에 귀 기울여 보세요.', 'https://genius.com/search?q=Nick%20Drake%20Place%20to%20Be'),
(403, 'Waltz #2 (XO)', 'Elliott Smith', 1998, 'Indie Rock', 2, '가족에게 남은 복잡한 기억', '흔들리는 선율과 가까운 보컬', '왈츠의 리듬 안에 쉽게 정리되지 않는 감정이 남아요.', 'https://genius.com/search?q=Elliott%20Smith%20Waltz%20%232%20%28XO%29'),
(404, 'Angeles', 'Elliott Smith', 1997, 'Indie Folk', 2, '유혹과 불안이 공존하는 순간', '촘촘한 핑거피킹과 낮은 음성', '빠르게 움직이는 기타와 조용한 목소리의 대비가 묘해요.', 'https://genius.com/search?q=Elliott%20Smith%20Angeles'),
(405, 'Casimir Pulaski Day', 'Sufjan Stevens', 2005, 'Indie Folk', 2, '상실 앞에서 흔들리는 믿음', '담담한 이야기와 섬세한 편곡', '슬픔을 크게 외치지 않는 방식이 오히려 오래 남아요.', 'https://genius.com/search?q=Sufjan%20Stevens%20Casimir%20Pulaski%20Day'),
(406, 'Should Have Known Better', 'Sufjan Stevens', 2015, 'Indie Folk', 2, '상실 이후에도 이어지는 삶', '여린 목소리에서 넓어지는 사운드', '작은 회상에서 시작해 조금씩 시야가 트이는 흐름이 좋아요.', 'https://genius.com/search?q=Sufjan%20Stevens%20Should%20Have%20Known%20Better'),
(407, 'Upward Over the Mountain', 'Iron & Wine', 2002, 'Indie Folk', 2, '어머니에게 건네는 마음', '속삭이는 보컬과 소박한 기타', '꾸밈없는 연주가 말로 꺼내기 어려운 마음을 대신해 줘요.', 'https://genius.com/search?q=Iron%20%26%20Wine%20Upward%20Over%20the%20Mountain'),
(408, 'Flightless Bird, American Mouth', 'Iron & Wine', 2007, 'Indie Folk', 2, '사랑과 시간의 낯선 비유', '온화한 기타와 느긋한 리듬', '따뜻한 선율 속에 어딘가 쓸쓸한 여운이 남아요.', 'https://genius.com/search?q=Iron%20%26%20Wine%20Flightless%20Bird%2C%20American%20Mouth'),
(409, 'Holocene', 'Bon Iver', 2011, 'Indie Folk', 2, '광대한 풍경 속의 작은 자신', '겹겹이 번지는 보컬과 리듬', '멀리 펼쳐지는 듯한 소리가 생각의 크기를 바꿔 줘요.', 'https://genius.com/search?q=Bon%20Iver%20Holocene'),
(410, 'Re: Stacks', 'Bon Iver', 2007, 'Indie Folk', 2, '관계를 정리하는 고요한 순간', '조용히 쌓이는 기타와 보컬', '끝내 남는 잔향을 따라가며 마음을 정돈하기 좋아요.', 'https://genius.com/search?q=Bon%20Iver%20Re%3A%20Stacks'),
(411, 'Blue Ridge Mountains', 'Fleet Foxes', 2008, 'Indie Folk', 2, '산과 숲을 닮은 기억', '화음이 넓게 펼쳐지는 포크록', '여러 목소리가 포개질 때 차가운 공기마저 따뜻해져요.', 'https://genius.com/search?q=Fleet%20Foxes%20Blue%20Ridge%20Mountains'),
(412, 'Mykonos', 'Fleet Foxes', 2008, 'Indie Folk', 2, '떠남과 되돌아봄', '힘 있게 치고 나오는 포크록', '절제된 시작에서 벗어나는 합창이 답답함을 털어 줘요.', 'https://genius.com/search?q=Fleet%20Foxes%20Mykonos'),
(413, 'Australia', 'The Shins', 2007, 'Indie Rock', 3, '기대와 현실 사이의 움직임', '경쾌한 기타와 탄력 있는 리듬', '가벼운 발걸음이 필요할 때 리듬을 따라가 보세요.', 'https://genius.com/search?q=The%20Shins%20Australia'),
