(415, 'I Will Follow You into the Dark', 'Death Cab for Cutie', 2005, 'Indie Rock', 2, '끝까지 함께하겠다는 약속', '단정한 기타와 낮은 목소리', '과장하지 않는 고백이 고요한 시간에 잘 어울려요.', 'https://genius.com/search?q=Death%20Cab%20for%20Cutie%20I%20Will%20Follow%20You%20into%20the%20Dark'),
(416, 'Soul Meets Body', 'Death Cab for Cutie', 2005, 'Indie Rock', 3, '몸과 마음의 거리를 좁히기', '움직임 있는 리듬과 선명한 멜로디', '한결 가벼워지는 박자에 생각을 잠시 맡겨 보세요.', 'https://genius.com/search?q=Death%20Cab%20for%20Cutie%20Soul%20Meets%20Body'),
(417, 'Such Great Heights', 'The Postal Service', 2003, 'Indietronica', 3, '멀리 떨어진 두 사람의 설렘', '반짝이는 전자음과 빠른 비트', '작은 전자음들이 모여 커다란 들뜸을 만들어 내요.', 'https://genius.com/search?q=The%20Postal%20Service%20Such%20Great%20Heights'),
