(419, 'Poison Oak', 'Bright Eyes', 2005, 'Indie Folk', 2, '잃어버린 사람을 향한 기억', '떨리는 목소리와 절박한 포크', '거친 숨결이 남는 노래라 감정을 억지로 덮지 않아요.', 'https://genius.com/search?q=Bright%20Eyes%20Poison%20Oak'),
(420, 'Lua', 'Bright Eyes', 2005, 'Indie Folk', 2, '밤의 거리를 함께 걷는 시간', '작은 목소리와 최소한의 반주', '속도를 낮춘 노래가 늦은 귀갓길에 자연스럽게 스며들어요.', 'https://genius.com/search?q=Bright%20Eyes%20Lua'),
(421, 'About Today', 'The National', 2004, 'Indie Rock', 2, '말하지 못한 이별의 징후', '느린 전개와 낮게 깔리는 감정', '크게 터뜨리지 않아도 관계의 침묵이 느껴지는 곡이에요.', 'https://genius.com/search?q=The%20National%20About%20Today'),
(422, 'I Need My Girl', 'The National', 2013, 'Indie Rock', 3, '멀어진 사람에게 보내는 마음', '낮고 단단한 리듬과 보컬', '무심한 듯 이어지는 목소리에 간절함이 묻어나요.', 'https://genius.com/search?q=The%20National%20I%20Need%20My%20Girl'),
(423, 'Red Eyes', 'The War on Drugs', 2014, 'Heartland Rock', 4, '되찾는 속도와 자유', '끝없이 달리는 기타와 드럼', '반복되는 박자가 멈춰 있던 기분을 다시 움직여 줘요.', 'https://genius.com/search?q=The%20War%20on%20Drugs%20Red%20Eyes'),
