(427, 'Shark Smile', 'Big Thief', 2017, 'Indie Rock', 4, '질주와 관계의 순간', '거칠게 튀는 기타와 생생한 리듬', '먼지 날리는 도로를 달리는 듯한 에너지가 있어요.', 'https://genius.com/search?q=Big%20Thief%20Shark%20Smile'),
