(431, 'Motion Sickness', 'Phoebe Bridgers', 2017, 'Indie Rock', 3, '관계를 떠올릴 때 찾아오는 멀미', '경쾌한 기타와 날 선 가사 정서', '밝은 속도와 불편한 감정의 충돌이 인상적이에요.', 'https://genius.com/search?q=Phoebe%20Bridgers%20Motion%20Sickness'),
