(433, 'Appointments', 'Julien Baker', 2017, 'Indie Rock', 2, '다시 만나자는 불완전한 약속', '조심스럽게 쌓이는 보컬과 기타', '확신 없는 마음을 숨기지 않는 목소리가 들려요.', 'https://genius.com/search?q=Julien%20Baker%20Appointments'),
(434, 'Turn Out the Lights', 'Julien Baker', 2017, 'Indie Rock', 2, '불을 끄고 마주하는 자신', '거친 감정이 번지는 기타와 보컬', '조용한 시작이 깊은 고백으로 이어지는 순간을 들어 봐요.', 'https://genius.com/search?q=Julien%20Baker%20Turn%20Out%20the%20Lights'),
(435, 'Night Shift', 'Lucy Dacus', 2018, 'Indie Rock', 4, '이별 후 길어지는 밤', '단단하게 치고 나오는 기타록', '쌓인 말을 한꺼번에 꺼내듯 커지는 소리가 시원해요.', 'https://genius.com/search?q=Lucy%20Dacus%20Night%20Shift'),
