-- 곡 추가 (501~933번: 2026-10 후보 433곡)
INSERT INTO songs (id, title, artist, year, genre, energy, theme, tone, reason, lyrics_url) VALUES
(501, 'Love Will Tear Us Apart', 'Joy Division', 1980, 'Post-Punk', 3, '무너져 가는 관계 앞의 무력감', '차갑게 맥박치는 베이스와 신스', '담담한 목소리라서 더 깊이 내려앉는 슬픔이에요.', 'https://genius.com/search?q=Joy%20Division%20Love%20Will%20Tear%20Us%20Apart'),
(502, 'A Forest', 'The Cure', 1980, 'Post-Punk', 3, '끝없이 이어지는 숲속의 추적', '안개처럼 퍼지는 기타와 반복되는 리듬', '같은 길을 맴도는 리듬에 생각을 맡겨 보세요.', 'https://genius.com/search?q=The%20Cure%20A%20Forest'),
(503, 'Primary', 'The Cure', 1981, 'Post-Punk', 4, '어린 시절이 끝나 가는 불안', '두 대의 베이스가 밀어붙이는 질주', '빠르게 몰아치는 베이스가 굳은 마음을 흔들어요.', 'https://genius.com/search?q=The%20Cure%20Primary'),
(504, 'The Lovecats', 'The Cure', 1983, 'New Wave', 4, '고양이처럼 장난스러운 사랑', '재즈풍 피아노와 통통 튀는 베이스', '의외의 유쾌함이 회색 하루에 웃음을 줘요.', 'https://genius.com/search?q=The%20Cure%20The%20Lovecats'),
(505, 'This Charming Man', 'The Smiths', 1983, 'Indie Rock', 4, '낯선 밤길에서 만난 매력적인 남자', '반짝이는 기타 리프와 경쾌한 리듬', '첫 소절부터 기분을 가볍게 들어 올려요.', 'https://genius.com/search?q=The%20Smiths%20This%20Charming%20Man'),
(506, 'Heaven Knows I''m Miserable Now', 'The Smiths', 1984, 'Indie Rock', 2, '일이 잘 풀려도 여전히 우울한 마음', '흔들리는 기타와 체념 섞인 보컬', '우울함을 꾸미지 않고 말해 줘서 오히려 위로가 돼요.', 'https://genius.com/search?q=The%20Smiths%20Heaven%20Knows%20I%27m%20Miserable%20Now'),
(507, 'William, It Was Really Nothing', 'The Smiths', 1984, 'Indie Rock', 3, '안주하려는 친구를 향한 쓴소리', '짧고 경쾌한 기타 팝', '2분 남짓한 곡이 답답한 마음을 툭 털어 줘요.', 'https://genius.com/search?q=The%20Smiths%20William%2C%20It%20Was%20Really%20Nothing'),
(508, 'The Headmaster Ritual', 'The Smiths', 1985, 'Indie Rock', 3, '억압적인 학교와 권위에 대한 반발', '뒤틀린 기타 리프와 날 선 보컬', '쌓인 불만을 차분하게 꺼내 보고 싶을 때 좋아요.', 'https://genius.com/search?q=The%20Smiths%20The%20Headmaster%20Ritual'),
(509, 'Radio Free Europe', 'R.E.M.', 1981, 'Alternative Rock', 4, '알아듣기 힘든 가사 속 묘한 활기', '찰랑이는 기타와 웅얼거리는 보컬', '가사보다 소리의 질감에 기대어 걷기 좋아요.', 'https://genius.com/search?q=R.E.M.%20Radio%20Free%20Europe'),
(510, 'Gardening at Night', 'R.E.M.', 1982, 'Alternative Rock', 3, '새벽까지 이어지는 막연한 기다림', '어둡게 울리는 기타와 고음 코러스', '조용한 밤에 생각을 정리하며 듣기 좋아요.', 'https://genius.com/search?q=R.E.M.%20Gardening%20at%20Night'),
(511, 'Driver 8', 'R.E.M.', 1985, 'Alternative Rock', 3, '남부 시골 풍경과 기차의 기억', '아르페지오 기타와 서늘한 공기', '창밖 풍경을 보며 이동할 때 잘 어울려요.', 'https://genius.com/search?q=R.E.M.%20Driver%208'),
(512, 'It''s the End of the World as We Know It (And I Feel Fine)', 'R.E.M.', 1987, 'Alternative Rock', 5, '세상이 끝나도 괜찮다는 역설', '숨 쉴 틈 없이 쏟아지는 가사와 질주', '빠른 말과 리듬에 머릿속 잡음이 날아가요.', 'https://genius.com/search?q=R.E.M.%20It%27s%20the%20End%20of%20the%20World%20as%20We%20Know%20It%20%28And%20I%20Feel%20Fine%29'),
(513, 'Bizarre Love Triangle', 'New Order', 1986, 'New Wave', 4, '확신과 혼란 사이를 오가는 사랑', '반짝이는 신스와 춤추는 비트', '들뜬 신스 사운드에 몸이 먼저 반응해요.', 'https://genius.com/search?q=New%20Order%20Bizarre%20Love%20Triangle'),
(514, 'Age of Consent', 'New Order', 1983, 'New Wave', 4, '떠나는 사람을 붙잡지 못하는 마음', '경쾌한 베이스 멜로디와 쓸쓸한 보컬', '밝은 리듬 아래 숨은 아쉬움이 묘하게 끌려요.', 'https://genius.com/search?q=New%20Order%20Age%20of%20Consent'),
(515, 'Ceremony', 'New Order', 1981, 'Post-Punk', 3, '끝과 시작이 겹치는 의식', '단단한 드럼과 겹겹이 쌓이는 기타', '담담하게 밀고 나가는 힘이 마음을 붙잡아 줘요.', 'https://genius.com/search?q=New%20Order%20Ceremony'),
(516, 'Temptation', 'New Order', 1982, 'New Wave', 4, '유혹 앞에서 흔들리는 마음', '길게 이어지는 신스 그루브', '천천히 고조되는 흐름이 몰입하게 만들어요.', 'https://genius.com/search?q=New%20Order%20Temptation'),
(517, 'Schizophrenia', 'Sonic Youth', 1987, 'Noise Rock', 3, '가까운 사람을 향한 혼란스러운 시선', '소음과 선율이 엉킨 기타', '거친 소리 속 선명한 멜로디를 찾아 보세요.', 'https://genius.com/search?q=Sonic%20Youth%20Schizophrenia'),
(518, 'Silver Rocket', 'Sonic Youth', 1988, 'Noise Rock', 5, '멈추지 않고 달리는 은빛 로켓', '폭주하는 기타 노이즈', '소음의 폭발이 답답한 기분을 날려 줘요.', 'https://genius.com/search?q=Sonic%20Youth%20Silver%20Rocket'),
(519, 'Death Valley ''69', 'Sonic Youth', 1985, 'Noise Rock', 5, '광기 어린 질주와 혼돈', '날카롭게 긁는 기타와 외침', '제어되지 않는 에너지를 그대로 쏟아내고 싶을 때예요.', 'https://genius.com/search?q=Sonic%20Youth%20Death%20Valley%20%2769'),
(520, 'Expressway to Yr. Skull', 'Sonic Youth', 1986, 'Noise Rock', 2, '고속도로 끝에서 만난 이상한 평화', '길게 퍼지는 기타 노이즈', '긴 곡의 반복 속에 생각이 천천히 가라앉아요.', 'https://genius.com/search?q=Sonic%20Youth%20Expressway%20to%20Yr.%20Skull'),
(521, 'Debaser', 'Pixies', 1989, 'Alternative Rock', 5, '초현실적인 영화 속 장면들', '갑자기 터지는 기타와 외침', '첫 베이스 라인부터 기운이 확 올라와요.', 'https://genius.com/search?q=Pixies%20Debaser'),
(522, 'Monkey Gone to Heaven', 'Pixies', 1989, 'Alternative Rock', 4, '오염된 바다와 무너지는 세계', '현악과 기타가 맞물린 긴장감', '조용한 구간과 폭발의 대비가 귀를 붙잡아요.', 'https://genius.com/search?q=Pixies%20Monkey%20Gone%20to%20Heaven'),
(523, 'Gigantic', 'Pixies', 1988, 'Alternative Rock', 4, '거대한 사랑을 향한 노래', '베이스가 이끄는 경쾌한 리듬', '가볍게 따라 부르며 기분을 띄우기 좋아요.', 'https://genius.com/search?q=Pixies%20Gigantic'),
(524, 'Bone Machine', 'Pixies', 1988, 'Alternative Rock', 5, '불안하게 뒤틀린 관계', '날카로운 드럼과 비명 같은 기타', '짧고 거친 폭발로 답답함을 털어내요.', 'https://genius.com/search?q=Pixies%20Bone%20Machine'),
(525, 'Fade to Black', 'Metallica', 1984, 'Thrash Metal', 3, '어둠 속으로 가라앉는 절망', '어쿠스틱으로 시작해 폭발하는 전개', '무거운 감정을 끝까지 따라가 보고 싶을 때예요.', 'https://genius.com/search?q=Metallica%20Fade%20to%20Black'),
(526, 'For Whom the Bell Tolls', 'Metallica', 1984, 'Thrash Metal', 5, '전쟁터의 종소리가 울리는 순간', '묵직하게 내리치는 리프', '한 걸음씩 밀어붙이는 리듬이 집중력을 깨워요.', 'https://genius.com/search?q=Metallica%20For%20Whom%20the%20Bell%20Tolls'),
(527, 'Battery', 'Metallica', 1986, 'Thrash Metal', 5, '전투처럼 몰아치는 속도', '빠르게 쏟아지는 다운피킹', '강한 속도감으로 막힌 에너지를 뚫어 줘요.', 'https://genius.com/search?q=Metallica%20Battery'),
(528, 'Patience', 'Guns N'' Roses', 1988, 'Hard Rock', 2, '기다림을 견디는 관계', '휘파람과 어쿠스틱 기타', '조급한 마음을 천천히 내려놓게 해 줘요.', 'https://genius.com/search?q=Guns%20N%27%20Roses%20Patience'),
(529, 'Nightrain', 'Guns N'' Roses', 1987, 'Hard Rock', 5, '밤 기차처럼 멈추지 않는 질주', '거칠게 달리는 기타 리프', '달리는 리듬에 처진 몸이 다시 깨어나요.', 'https://genius.com/search?q=Guns%20N%27%20Roses%20Nightrain'),
(530, 'Mr. Brownstone', 'Guns N'' Roses', 1987, 'Hard Rock', 4, '위험한 습관에 끌려가는 하루', '흔들리는 그루브와 거친 보컬', '들썩이는 리듬에 답답함이 풀려요.', 'https://genius.com/search?q=Guns%20N%27%20Roses%20Mr.%20Brownstone'),
(531, 'Where the Streets Have No Name', 'U2', 1987, 'Rock', 4, '이름 없는 곳을 향한 갈망', '서서히 차오르는 기타 딜레이', '천천히 열리는 전주가 하루를 넓게 펼쳐 줘요.', 'https://genius.com/search?q=U2%20Where%20the%20Streets%20Have%20No%20Name'),
(532, 'New Year''s Day', 'U2', 1983, 'Post-Punk', 4, '새해 아침에도 계속되는 갈등', '피아노와 묵직한 베이스', '차가운 공기 속에서 다짐을 새기기 좋아요.', 'https://genius.com/search?q=U2%20New%20Year%27s%20Day'),
(533, 'Sunday Bloody Sunday', 'U2', 1983, 'Rock', 5, '반복되는 폭력에 대한 분노', '군가처럼 울리는 드럼', '단호한 리듬이 흐트러진 마음을 다잡아 줘요.', 'https://genius.com/search?q=U2%20Sunday%20Bloody%20Sunday'),
