(914, 'Guilty Party', 'The National', 2017, 'Indie Rock', 2, '서로를 탓하는 이별의 순간', '전자 비트와 낮은 보컬', '무거운 날 감정을 천천히 가라앉혀 줘요.', 'https://genius.com/search?q=The%20National%20Guilty%20Party'),
(915, 'Graceless', 'The National', 2013, 'Indie Rock', 4, '은총 없이 버티는 마음', '빠른 드럼과 고조되는 보컬', '달리는 리듬이 버틸 힘을 줘요.', 'https://genius.com/search?q=The%20National%20Graceless'),
(916, 'The Way You Used to Do', 'Queens of the Stone Age', 2017, 'Stoner Rock', 4, '예전처럼 사랑해 주길 바라는 마음', '흔들리는 그루브와 박수', '들썩이는 리듬에 몸이 가벼워져요.', 'https://genius.com/search?q=Queens%20of%20the%20Stone%20Age%20The%20Way%20You%20Used%20to%20Do'),
(917, 'I Sat by the Ocean', 'Queens of the Stone Age', 2013, 'Stoner Rock', 3, '바닷가에 앉아 기다리는 마음', '느긋한 리프와 그루브', '느긋한 흐름에 생각이 천천히 풀려요.', 'https://genius.com/search?q=Queens%20of%20the%20Stone%20Age%20I%20Sat%20by%20the%20Ocean'),
(918, 'My God Is the Sun', 'Queens of the Stone Age', 2013, 'Stoner Rock', 5, '태양을 신으로 섬기는 열기', '육중한 리프와 빠른 드럼', '강한 리듬이 집중력을 끌어올려요.', 'https://genius.com/search?q=Queens%20of%20the%20Stone%20Age%20My%20God%20Is%20the%20Sun'),
(919, 'Hooka', '혁오', 2015, 'Korean Indie Rock', 3, '연기처럼 흐르는 시간', '느긋한 기타와 그루브', '느긋한 리듬에 마음이 풀려요.', 'https://genius.com/search?q=%ED%98%81%EC%98%A4%20Hooka'),
(920, 'Ohio', '혁오', 2014, 'Korean Indie Rock', 3, '먼 곳을 향한 막연한 동경', '부드러운 기타와 낮은 보컬', '맑은 날 산책길에 잘 어울려요.', 'https://genius.com/search?q=%ED%98%81%EC%98%A4%20Ohio'),
(921, 'Panda Bear', '혁오', 2015, 'Korean Indie Rock', 4, '판다처럼 느긋한 하루', '경쾌한 기타와 그루브', '가볍게 흔들리며 듣기 좋아요.', 'https://genius.com/search?q=%ED%98%81%EC%98%A4%20Panda%20Bear'),
(922, 'She', '잔나비', 2016, 'Korean Indie Rock', 3, '그녀를 향한 고백', '복고풍 기타와 따뜻한 보컬', '따뜻한 멜로디에 마음이 포근해져요.', 'https://genius.com/search?q=%EC%9E%94%EB%82%98%EB%B9%84%20She'),
(923, '알록달록', '잔나비', 2019, 'Korean Indie Rock', 3, '알록달록한 추억', '경쾌한 기타와 복고풍 멜로디', '밝은 색감의 멜로디에 기분이 환해져요.', 'https://genius.com/search?q=%EC%9E%94%EB%82%98%EB%B9%84%20%EC%95%8C%EB%A1%9D%EB%8B%AC%EB%A1%9D'),
(924, '변신', '국카스텐', 2014, 'Korean Psychedelic Rock', 5, '모습을 바꾸며 확장되는 나', '강렬한 기타와 폭발하는 고음', '폭발하는 에너지가 정신을 깨워요.', 'https://genius.com/search?q=%EA%B5%AD%EC%B9%B4%EC%8A%A4%ED%85%90%20%EB%B3%80%EC%8B%A0'),
(925, 'Pulse', '국카스텐', 2017, 'Korean Psychedelic Rock', 4, '심장 박동처럼 뛰는 리듬', '맥박 같은 드럼과 사이키델릭 기타', '규칙적인 맥박 같은 리듬에 몰입해요.', 'https://genius.com/search?q=%EA%B5%AD%EC%B9%B4%EC%8A%A4%ED%85%90%20Pulse'),
(926, '도둑', '국카스텐', 2014, 'Korean Psychedelic Rock', 4, '무언가를 훔쳐 가는 존재', '뒤틀린 기타와 강렬한 보컬', '날 선 사운드가 답답함을 긁어 줘요.', 'https://genius.com/search?q=%EA%B5%AD%EC%B9%B4%EC%8A%A4%ED%85%90%20%EB%8F%84%EB%91%91'),
(927, 'Green Nocturne', '넬', 2014, 'Korean Indie Rock', 2, '녹색 빛으로 번지는 밤', '몽환적인 기타와 섬세한 보컬', '고요한 밤 감정에 잠기기 좋아요.', 'https://genius.com/search?q=%EB%84%AC%20Green%20Nocturne'),
(928, 'Jackie Down the Line', 'Fontaines D.C.', 2022, 'Post-Punk', 4, '무너지는 관계를 바라보는 시선', '서늘한 기타와 낮은 보컬', '어두운 긴장감에 생각이 또렷해져요.', 'https://genius.com/search?q=Fontaines%20D.C.%20Jackie%20Down%20the%20Line'),
(929, 'Wet Dream', 'Wet Leg', 2021, 'Post-Punk', 4, '아찔하게 엉뚱한 꿈', '건조한 기타와 장난스러운 보컬', '엉뚱한 유머에 기분이 가벼워져요.', 'https://genius.com/search?q=Wet%20Leg%20Wet%20Dream'),
(930, 'BLACKOUT', 'Turnstile', 2021, 'Hardcore Punk', 5, '정신이 끊기는 순간의 폭발', '육중한 리프와 외침', '짧고 강렬한 폭발로 답답함을 날려요.', 'https://genius.com/search?q=Turnstile%20BLACKOUT'),
(931, 'Dancer', 'IDLES', 2023, 'Post-Punk', 4, '춤추는 사람들 속의 해방', '날카로운 기타와 반복되는 리듬', '반복되는 리듬에 몸을 맡겨 보세요.', 'https://genius.com/search?q=IDLES%20Dancer'),
(932, 'The Last Man on Earth', 'Wolf Alice', 2021, 'Indie Rock', 2, '지구 최후의 사람 같은 고독', '피아노와 서서히 고조되는 밴드', '천천히 커지는 소리가 마음을 넓게 열어 줘요.', 'https://genius.com/search?q=Wolf%20Alice%20The%20Last%20Man%20on%20Earth'),
