-- id를 직접 넣었으므로 다음 자동 번호를 마지막 id 뒤로 맞춥니다.
SELECT setval(pg_get_serial_sequence('songs', 'id'), (SELECT MAX(id) FROM songs));

-- 4) 웹앱의 data.json과 같은 모양으로 보는 뷰 (기분·날씨는 쉼표로 이은 글자)
CREATE VIEW v_songs WITH (security_invoker = true) AS
SELECT s.id, s.title, s.artist, s.year, s.genre, s.energy,
       (SELECT string_agg(mood,    ',' ORDER BY mood)    FROM song_moods    WHERE song_id = s.id) AS moods,
       (SELECT string_agg(weather, ',' ORDER BY weather) FROM song_weathers WHERE song_id = s.id) AS weathers,
       s.theme, s.tone, s.reason, s.lyrics_url
FROM songs s;

-- 5) Supabase 보안: 브라우저용 공개 API(anon 키)로 이 테이블을 읽거나 쓰지 못하게 막습니다.
--    서버(FastAPI)는 DB 비밀번호로 직접 접속하므로 영향을 받지 않습니다.
ALTER TABLE songs         ENABLE ROW LEVEL SECURITY;
ALTER TABLE song_moods    ENABLE ROW LEVEL SECURITY;
ALTER TABLE song_weathers ENABLE ROW LEVEL SECURITY;

COMMIT;

-- 6) 확인용 (결과: 933 / 2046 / 2006)
SELECT
  (SELECT COUNT(*) FROM songs)         AS songs,
  (SELECT COUNT(*) FROM song_moods)    AS moods,
  (SELECT COUNT(*) FROM song_weathers) AS weathers;
